insert into public.bov_hub_records(category,title,summary,sectors,source_url,source_reference,verification,verified_at,details)
select 'contact','UNDP — Oana Maria Rebedea, Regional Partnership Specialist','Named partnership contact for UNDP Europe and Central Asia; not a global grant decision-maker.',array['Partnerships','Governance']::text[],'https://www.undp.org/eurasia/our-partners','Official agency page checked 2026-11-13','verified',now(),'{"agency":"UNDP","person":"Oana Maria Rebedea","role":"Regional Partnership Specialist","email":"oana.maria.rebedea@undp.org","geography":"Europe and Central Asia","contact_type":"Named institutional contact","verified_scope":"Public official source only; recheck before outreach","verified_on":"2026-11-13"}'::jsonb
where not exists(select 1 from public.bov_hub_records where category='contact' and title='UNDP — Oana Maria Rebedea, Regional Partnership Specialist');

