insert into public.bov_hub_records(category,title,summary,sectors,source_url,source_reference,verification,verified_at,details)
select 'funding','UNESCO Participation Programme — 2026–2027 verified criteria','UNESCO Participation Programme supports Member State proposals and NGOs in official partnership. The 2026–2027 ceilings are US$26,000 national, US$28,000 subregional/interregional and US$38,000 regional. The Member State submission deadline was 27 February 2026; this is not an open call.',array['Education','Culture','Science','Gender equality']::text[],'https://www.unesco.org/en/member-states-portal/participation-programme?hub=66535','Official agency page checked 2026-11-13','verified',now(),'{"agency":"UNESCO","programme":"Participation Programme","cycle":"2026–2027","funding_caps_usd":{"national":26000,"subregional_or_interregional":28000,"regional":38000},"member_state_submission_deadline":"2026-02-27","deadline_status":"Past","eligible_applicants":["Member States via National Commission or designated channel","NGOs in official partnership with UNESCO subject to programme rules"],"ngo_limit":"Up to 2 subregional/regional/interregional requests, supported by relevant Member States","member_state_limit":"Up to 7 requests per Member State","mechanism":"Programme assistance, not unrestricted funding","open_call_confirmed":false,"verified_scope":"Public official source only; recheck before outreach","verified_on":"2026-11-13"}'::jsonb
where not exists(select 1 from public.bov_hub_records where category='funding' and title='UNESCO Participation Programme — 2026–2027 verified criteria');

